-- 04-pgr.sql (HCM 2.1, tenant mz): PGR (complaints) service config.
-- REBUILT 2026-08-21 from hcm-demo (schema `demo`, tenantid 'demo'), demo->mz.
--
-- The previous revision of this file carried a DIFFERENT state machine from the reference
-- environment: legacy urban-DIGIT PGR (PENDINGFORASSIGNMENT / PENDINGATLB / CLOSEDAFTERRESOLUTION,
-- business='PGR') plus 41 urban complaint types (NoStreetlight, IllegalShopsOnFootPath, ...).
-- Critically it defined NO state with an EMPTY name. DIGIT resolves a NEW application's initial
-- state by scanning for exactly that (egov-workflow-v2 TransitionService.java:74-80), so every
-- complaint create failed 400 with
--     NullPointerException: Cannot invoke "State.getActions()" because
--     ProcessStateAndAction.getCurrentState() is null
-- i.e. NO complaint could be raised on any cluster installed from this seed.
--
-- This revision mirrors the reference environment exactly: business='pgr-services',
-- 5 states (incl. 1 empty-named start state), 7 actions, 17 MDMS rows.
-- Transitions: CREATE -> PENDING_ASSIGNMENT; ASSIGN -> ASSIGNED; RESOLVE/REJECT from either
-- PENDING_ASSIGNMENT or ASSIGNED. RESOLVED and REJECTED are terminal.
--
-- Idempotent. The old, wrong workflow is removed first - it uses different state names, so a plain
-- upsert would leave both machines present under the same businessservice name.

BEGIN;

-- eg_pgr_service_v2.hierarchytype: added upstream by pgr-services migration
-- V20260818120000__add_hierarchytype.sql. The deployed pgr-services rowmapper reads this column
-- unconditionally, so a cluster whose pgr-services-db image predates 2026-08-18 fails EVERY
-- complaint update with "The column name hierarchytype was not found in this ResultSet" (400
-- QUERY_EXECUTION_ERROR). Guarded so it is a no-op where the migration already ran.
ALTER TABLE eg_pgr_service_v2 ADD COLUMN IF NOT EXISTS hierarchytype character varying(64);


-- remove the superseded legacy workflow (uuids pgr-bs-mz / pgr-st-* / pgr-ac-* from the old file)
DELETE FROM eg_wf_action_v2 WHERE currentstate IN (SELECT uuid FROM eg_wf_state_v2 WHERE businessserviceid='pgr-bs-mz')
                               OR nextstate    IN (SELECT uuid FROM eg_wf_state_v2 WHERE businessserviceid='pgr-bs-mz');
DELETE FROM eg_wf_state_v2 WHERE businessserviceid='pgr-bs-mz';
DELETE FROM eg_wf_businessservice_v2 WHERE uuid='pgr-bs-mz';


-- business service
INSERT INTO eg_wf_businessservice_v2 (businessservice, business, tenantid, uuid, geturi, posturi, createdby, createdtime, lastmodifiedby, lastmodifiedtime, businessservicesla) VALUES ('PGR', 'pgr-services', 'mz', '830e5162-953f-483f-8ed5-0a943ecddf33', NULL, NULL, 'ee3ff74c-518b-4740-aed0-514e487a16b0', 1783449141726, 'ee3ff74c-518b-4740-aed0-514e487a16b0', 1783449141726, 432000000) ON CONFLICT (uuid) DO UPDATE SET business=EXCLUDED.business, businessservicesla=EXCLUDED.businessservicesla;

